 "content": "def transform(grid):
    """Extend each solid 3x3 square along its middle row and column."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    squares = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                squares.append((r + 1, c + 1, color))

    # Record the colors each square's two full-length rays demand at every cell.
    demands = {}
    for cr, cc, color in squares:
        for x in range(w):
            demands.setdefault((cr, x), set()).add(color)
        for y in range(h):
            demands.setdefault((y, cc), set()).add(color)

    for (r, c), colors in demands.items():
        if len(colors) > 1:
            # Crossings between rays of different colors are left empty.
            if grid[r][c] == 0:
                out[r][c] = 0
        elif grid[r][c] == 0:
            out[r][c] = next(iter(colors))
    return out
